import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"RenderCommand","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/render-command.md","filePath":"zh/api/render-command.md","lastUpdated":1786971590000}'),o={name:"zh/api/render-command.md"};function c(n,t,i,l,h,m){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="rendercommand" tabindex="-1">RenderCommand <a class="header-anchor" href="#rendercommand" aria-label="Permalink to &quot;RenderCommand&quot;">​</a></h1><p>渲染命令结构体，描述 Render 层需要执行的绘制操作。</p><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>RenderCommand</code> 是 Application 层与 Render 层之间的通信单元。每个命令包含类型和对应的参数。</p><h2 id="命令类型" tabindex="-1">命令类型 <a class="header-anchor" href="#命令类型" aria-label="Permalink to &quot;命令类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>kNoop</code></td><td>空操作</td></tr><tr><td><code>kBeginFrame</code></td><td>开始新帧</td></tr><tr><td><code>kEndFrame</code></td><td>结束帧，提交并交换缓冲区</td></tr><tr><td><code>kDrawRect</code></td><td>绘制矩形</td></tr><tr><td><code>kDrawRoundedRect</code></td><td>绘制圆角矩形</td></tr><tr><td><code>kDrawText</code></td><td>绘制文本（UTF-8）</td></tr><tr><td><code>kClipRect</code></td><td>设置裁剪区域</td></tr><tr><td><code>kTranslate</code></td><td>平移变换</td></tr><tr><td><code>kSave</code></td><td>保存渲染状态</td></tr><tr><td><code>kRestore</code></td><td>恢复渲染状态</td></tr></tbody></table><h2 id="工厂方法" tabindex="-1">工厂方法 <a class="header-anchor" href="#工厂方法" aria-label="Permalink to &quot;工厂方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>MakeBeginFrame()</code></td><td>创建开始帧命令</td></tr><tr><td><code>MakeEndFrame()</code></td><td>创建结束帧命令</td></tr><tr><td><code>MakeDrawRect(rect, color)</code></td><td>创建绘制矩形命令</td></tr><tr><td><code>MakeDrawRoundedRect(rect, color, radius)</code></td><td>创建绘制圆角矩形命令</td></tr><tr><td><code>MakeDrawText(text, pos, color, size, font)</code></td><td>创建绘制文本命令</td></tr><tr><td><code>MakeClipRect(rect)</code></td><td>创建裁剪命令</td></tr><tr><td><code>MakeTranslate(x, y)</code></td><td>创建平移命令</td></tr><tr><td><code>MakeSave()</code></td><td>创建保存状态命令</td></tr><tr><td><code>MakeRestore()</code></td><td>创建恢复状态命令</td></tr></tbody></table><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./render-context">RenderContext</a></li><li><a href="./../guide/rendering">渲染管线指南</a></li></ul>',10)])])}const p=d(o,[["render",c]]);export{k as __pageData,p as default};
